  test "every admitted Ash resource: real Ash ETS create/read round-trips every field" do
    Enum.each(@resources, fn res ->
      created =
        res.mod
        |> Ash.Changeset.for_create(:create, res.params)
        |> Ash.create!()

      [read_back] = Ash.read!(res.mod)
      assert read_back.id == created.id, "#{res.name}: read-back id did not match created id"

      Enum.each(res.expected, fn {k, v} ->
        got = Map.get(read_back, k)

        ok? =
          case {v, got} do
            {%DateTime{}, %DateTime{}} -> DateTime.compare(got, v) == :eq
            _ -> got == v
          end

        assert ok?,
               "#{res.name}: field #{k} expected #{inspect(v)}, got #{inspect(got)}"
      end)
    end)
  end
end

